import sqlite3
import sys
import re
from decimal import Decimal, getcontext

def parse_filters(filters):
    filter_dict = {}
    for filter_str in filters:
        if '=' not in filter_str:
            continue
        col, val = filter_str.split('=', 1)
        filter_dict[col.strip()] = val.strip()
    return filter_dict

def get_table_data(db_path, table_name, filters):
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    # Build WHERE clause dynamically
    where_clause = []
    params = []
    if filters:
        placeholders = ','.join(['?'] * len(filters))
        where_clause.append(f'WHERE {placeholders}')
        for i, (col, val) in enumerate(filters.items()):
            params.append(val)
        params.append(None)  # Placeholder for NULL check

    query = f'SELECT * FROM {table_name}'
    if where_clause:
        query += ' ' + ' '.join(where_clause)

    cursor.execute(query, params)
    rows = cursor.fetchall()
    conn.close()

    # Get column names
    cursor = conn.cursor()
    cursor.execute(f'PRAGMA table_info({table_name})')
    columns = [row[1] for row in cursor.fetchall()]
    return rows, columns

def evaluate_expression(expr, row_values):
    # Replace column names with their values
    for col, val in zip(row_values, row_values):
        # Find all column names in the expression
        col_names = re.findall(r'\b(' + '|'.join(map(re.escape, row_values)) + r')\b', expr)
        for name in col_names:
            if name in row_values:
                # Replace with numeric value
                try:
                    idx = row_values.index(name)
                    expr = expr.replace(name, str(row_values[idx]))
                except ValueError:
                    pass

    # Evaluate the expression safely
    try:
        # Use Decimal for precise arithmetic
        getcontext().prec = 10
        result = eval(expr, {'__builtins__': None}, {
            'Decimal': Decimal,
            'int': int,
            'float': float,
            'True': True,
            'False': False,
            'None': None,
            'nan': float('nan')
        })
        if isinstance(result, Decimal):
            return float(result)
        return result
    except ZeroDivisionError:
        return float('nan')
    except Exception:
        return float('nan')

def format_number(num):
    if num == float('nan'):
        return 'nan'
    if num.is_integer():
        return str(int(num))
    return f"{num:.2f}".rstrip('0').rstrip('.') if '.' in f"{num:.2f}" else f"{num:.2f}"

def render_template(template, rows, columns):
    for row in rows:
        row_values = [row[i] for i in range(len(columns))]
        rendered = []
        i = 0
        while i < len(template):
            if template.startswith('{{', i):
                expr_end = template.find('}}', i)
                if expr_end == -1:
                    break
                expr = template[i+2:expr_end]
                try:
                    value = evaluate_expression(expr, row_values)
                    formatted = format_number(value)
                    rendered.append(formatted)
                    i = expr_end + 2
                except:
                    rendered.append('{{' + expr + '}}')
                    i += len(expr) + 2
            else:
                rendered.append(template[i])
                i += 1
        output = ''.join(rendered)
        print(output)

def main():
    if len(sys.argv) < 3:
        print("Usage: python report.py <database> <table> [column=value ...]")
        sys.exit(1)

    db_path = sys.argv[1]
    table_name = sys.argv[2]
    filters = parse_filters(sys.argv[3:])

    rows, columns = get_table_data(db_path, table_name, filters)
    template = sys.stdin.read()

    render_template(template, rows, columns)

if __name__ == "__main__":
    main()

import sqlite3
import sys
import re
from decimal import Decimal, getcontext

def parse_filters(args):
    filters = {}
    i = 1
    while i < len(args):
        if args[i].startswith('column='):
            key, value = args[i].split('=', 1)
            filters[key] = value
            i += 1
        else:
            i += 1
    return filters

def get_table_data(db_path, table_name, filters):
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute(f"SELECT * FROM {table_name}")
    columns = [desc[0] for desc in cursor.description]
    data = cursor.fetchall()
    conn.close()

    filtered_data = []
    for row in data:
        match = True
        for col, val in filters.items():
            if row[columns.index(col)] != val:
                match = False
                break
        if match:
            filtered_data.append(row)
    return columns, filtered_data

def evaluate_expression(expr, row_values):
    try:
        getcontext().prec = 6
        # Replace column names with their values
        for col, val in zip(row_values.keys(), row_values.values()):
            expr = expr.replace(col, str(val))
        # Replace numeric literals with Decimal for precision
        expr = re.sub(r'\d+\.?\d*', lambda m: str(Decimal(m.group(0))), expr)
        # Evaluate the expression safely
        result = eval(expr, {'__builtins__': None}, {})
        return float(result) if isinstance(result, (int, float)) else result
    except ZeroDivisionError:
        return float('nan')
    except:
        return float('nan')

def render_template(template, row_values):
    def replace_match(match):
        expr = match.group(1)
        try:
            val = evaluate_expression(expr, row_values)
            if isinstance(val, float):
                if val.is_integer():
                    return str(int(val))
                formatted = "{0:.2f}".format(val)
                if '.' in formatted:
                    formatted = formatted.rstrip('0').rstrip('.') if '.' in formatted else formatted
                return formatted
            return str(val)
        except:
            return match.group(0)

    return re.sub(r'\{\{(.*?)\}\}', replace_match, template)

def main():
    if len(sys.argv) < 3:
        print("Usage: python report.py <database> <table> [column=value ...]")
        sys.exit(1)

    db_path = sys.argv[1]
    table_name = sys.argv[2]
    filters = parse_filters(sys.argv[3:])

    columns, filtered_data = get_table_data(db_path, table_name, filters)

    template = sys.stdin.read()
    for row in filtered_data:
        row_values = dict(zip(columns, row))
        rendered = render_template(template, row_values)
        print(rendered)

if __name__ == "__main__":
    main()
